public class SearchResult { public final boolean found; public final int index; public final long steps,timeNanos; public SearchResult(boolean f,int i,long s,long t){found=f;index=i;steps=s;timeNanos=t;} public void display(String name){System.out.println("\n"+name);System.out.println("--------------------------------");System.out.println("Result : "+(found?"Found":"Not Found"));if(found)System.out.println("Index  : "+index);System.out.println("Steps  : "+steps);System.out.println("Time   : "+timeNanos+" ns");} }
